from lib import draw_border, fill_line_gaps

def transform(grid):
    return fill_line_gaps(draw_border(grid, 2), 2, continue_line=True)

def draw_border(grid, color):
    """Color every background cell on the border of the non-background cells' bounding box, keeping marked cells."""
    bg = background(grid)
    t, l, b, r = bbox(grid)
    out = [row[:] for row in grid]
    for j in range(l, r + 1):
        for i in (t, b):
            if out[i][j] == bg:
                out[i][j] = color
    for i in range(t, b + 1):
        for j in (l, r):
            if out[i][j] == bg:
                out[i][j] = color
    return out

def fill_line_gaps(grid, color, continue_line=False):
    """Fill background cells sandwiched between two marked (non-background, non-color) cells in their row or column; with continue_line, only when the marked line continues on one side two cells away."""
    bg = background(grid)
    h, w = len(grid), len(grid[0])
    def mark(v):
        return v != bg and v != color
    out = [row[:] for row in grid]
    for i in range(h):
        for j in range(1, w - 1):
            a, m, c = out[i][j-1], out[i][j], out[i][j+1]
            if m == bg and mark(a) and mark(c) and (not continue_line or (j > 1 and mark(out[i][j-2])) or (j + 2 < w and mark(out[i][j+2]))):
                out[i][j] = color
    for j in range(w):
        for i in range(1, h - 1):
            a, m, c = out[i-1][j], out[i][j], out[i+1][j]
            if m == bg and mark(a) and mark(c) and (not continue_line or (i > 1 and mark(out[i-2][j])) or (i + 2 < h and mark(out[i+2][j]))):
                out[i][j] = color
    return out

